using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process", "Microsoft.Data",
        "Microsoft.EntityFrameworkCore", "System.Text.Json", "Newtonsoft",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(IPaymentGateway).Assembly;
    private static readonly Assembly Infrastructure = typeof(FileSystemReceiptStore).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_Application_or_Infrastructure() =>
        AssertNoViolations(Types.InAssembly(Domain)
            .ShouldNot().HaveDependencyOnAny("PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoViolations(Types.InAssembly(Application)
            .ShouldNot().HaveDependencyOn("PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNoViolations(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNoViolations(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    private static void AssertNoViolations(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violations: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
